style.css:
@-moz-document domain("chat.openai.com") {
/* CRYSTAL BLUE CHAT BUBBLES */
  .prose.border-token-main-surface-primary {
    background-color: #009dff !important; /* Bright Crystal Blue */
    color: white !important;
    border-radius: 1.5rem !important; /* Extra round corners */
    box-shadow: 0 0 10px rgba(0, 157, 255, 0.5);
  }

  /* YOUR MESSAGES */
  .bg-token-main-surface-primary {
    background-color: #006bb3 !important; /* Darker blue for contrast */
    color: white !important;
    border-radius: 1.5rem !important;
    box-shadow: 0 0 8px rgba(0, 107, 179, 0.5);
  }

  /* SEND BUTTON CRYSTAL BLUE GLOW */
  button[data-testid="send-button"] {
    background-color: #009dff !important;
    color: white !important;
    border-radius: 9999px !important;
    box-shadow: 0 0 10px rgba(0, 157, 255, 0.7);
    transition: transform 0.1s ease-in-out;
  }

  button[data-testid="send-button"]:hover {
    transform: scale(1.1);
    box-shadow: 0 0 14px rgba(0, 157, 255, 1);
  }

  /* SCROLLBAR GLOW (extra flair) */
  ::-webkit-scrollbar-thumb {
    background-color: #009dff !important;
    border-radius: 9999px;
  }

  /* LINK COLORS (so they match accent) */
  a {
    color: #00c3ff !important;
    text-decoration: underline;
  }
}
